import React from "react";
import { Link } from "react-router-dom";

const Header = () => {
  return <div className="bg-slate-200">
    <div className="flex font-bold justify-between max-w-6xl mx-auto p-3">
      <Link to='/'>
      </Link>
      
      <ul className="flex gap-4">
        <li>Home</li>
        <li>About</li> 
        <li>Sign In</li>

      </ul>
    </div>
  </div>;
};

export default Header;
